cssCode:
.quiz-card-wrap {
  perspective: 1000px;
  width: 260px; height: 320px;
  cursor: pointer;
}
.quiz-card {
  width: 100%; height: 100%;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.quiz-card.flipped { transform: rotateY(180deg); }
.card-face {
  position: absolute; width: 100%; height: 100%;
  backface-visibility: hidden; border-radius: 20px;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  font-family: sans-serif; color: #fff; padding: 20px; box-sizing: border-box;
  box-shadow: 0 15px 35px rgba(0,0,0,0.4);
}
.card-front {
  background: linear-gradient(135deg, #6c63ff, #3b2fad);
  border: 1px solid rgba(108,99,255,0.4);
}
.card-back {
  background: linear-gradient(135deg, #00ffcc, #00997a);
  transform: rotateY(180deg); color: #000;
  border: 1px solid rgba(0,255,204,0.4);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'quiz-card-wrap';

const card = document.createElement('div');
card.className = 'quiz-card';

const front = document.createElement('div');
front.className = 'card-front';
front.innerHTML = '<h2 style="margin:0;">QUESTION?</h2><p>Tap to reveal answer</p>';

const back = document.createElement('div');
back.className = 'card-back';
back.innerHTML = '<h2 style="margin:0;">ANSWER!</h2><p>Correct option is A</p>';

card.appendChild(front);
card.appendChild(back);
wrap.appendChild(card);
c.appendChild(wrap);

wrap.addEventListener('click', () => {
  card.classList.toggle('flipped');
});
